import type { ProjectFile } from '../types';
import { baseDirFor, isIgnoredPath, kindFor, mimeFor } from './file-kind';
import { BrowserOverlay } from './overlay';
import type { PreviewSource } from './types';

interface ManifestEntry {
  name: string;
  size: number;
  mtime: number;
}

function encodeSegments(path: string): string {
  return path.split('/').map((seg) => encodeURIComponent(seg)).join('/');
}

/**
 * A project served as plain static files with a `manifest.json` listing them
 * (generated by the Vite plugin in vite.config.ts for folders under public/).
 * Used for the bundled demo project; works for any static host.
 *
 * Static hosting is read-only, so edits (manual edit, sketches, new
 * documents, uploads) go into a browser overlay that shadows the served files.
 */
export class StaticSource implements PreviewSource {
  readonly kind = 'static' as const;
  readonly writeMode = 'browser' as const;
  readonly id: string;
  readonly description: string;
  private readonly base: string;
  private readonly overlay: BrowserOverlay;
  private readonly listeners = new Set<(changed: string[] | null) => void>();

  constructor(
    baseUrl: string,
    readonly label: string,
  ) {
    this.base = new URL(baseUrl.endsWith('/') ? baseUrl : `${baseUrl}/`, window.location.href).href;
    this.id = `static:${this.base}`;
    this.description = this.base;
    this.overlay = new BrowserOverlay(this.id);
  }

  async listFiles(signal?: AbortSignal): Promise<ProjectFile[]> {
    const [resp] = await Promise.all([fetch(`${this.base}manifest.json`, { cache: 'no-store', signal }), this.overlay.ready]);
    if (!resp.ok) throw new Error(`manifest.json request failed (${resp.status})`);
    const json = (await resp.json()) as { files?: ManifestEntry[] };
    const byName = new Map<string, ProjectFile>();
    for (const entry of json.files ?? []) {
      if (isIgnoredPath(entry.name)) continue;
      byName.set(entry.name, { name: entry.name, size: entry.size, mtime: entry.mtime, kind: kindFor(entry.name), mime: mimeFor(entry.name) });
    }
    for (const [name, entry] of this.overlay.entries()) {
      byName.set(name, { name, size: entry.blob.size, mtime: entry.mtime, kind: kindFor(name), mime: mimeFor(name) });
    }
    return [...byName.values()];
  }

  fileUrl(name: string, version?: number): string {
    const overlaid = this.overlay.url(name);
    if (overlaid) return overlaid;
    const url = `${this.base}${encodeSegments(name)}`;
    return version ? `${url}?v=${Math.round(version)}` : url;
  }

  baseHrefFor(name: string): string {
    return `${this.base}${encodeSegments(baseDirFor(name))}`;
  }

  overlayPaths(): ReadonlySet<string> {
    return this.overlay.paths();
  }

  async readText(name: string, options?: { fresh?: boolean }): Promise<string | null> {
    await this.overlay.ready;
    const overlaid = this.overlay.get(name);
    if (overlaid) return overlaid.blob.text();
    try {
      const resp = await fetch(`${this.base}${encodeSegments(name)}`, { cache: options?.fresh ? 'no-store' : 'default' });
      return resp.ok ? await resp.text() : null;
    } catch {
      return null;
    }
  }

  async readBlob(name: string): Promise<Blob | null> {
    await this.overlay.ready;
    const overlaid = this.overlay.get(name);
    if (overlaid) return overlaid.blob;
    try {
      const resp = await fetch(`${this.base}${encodeSegments(name)}`);
      return resp.ok ? await resp.blob() : null;
    } catch {
      return null;
    }
  }

  async writeFile(name: string, content: string | Blob): Promise<ProjectFile> {
    await this.overlay.ready;
    const entry = await this.overlay.write(name, content);
    for (const listener of this.listeners) listener([name]);
    return { name, size: entry.blob.size, mtime: entry.mtime, kind: kindFor(name), mime: mimeFor(name) };
  }

  hasLocalChanges(): boolean {
    return this.overlay.size > 0;
  }

  async discardLocalChanges(): Promise<void> {
    await this.overlay.clear();
    for (const listener of this.listeners) listener(null);
  }

  watch(onChange: (changed: string[] | null) => void): () => void {
    this.listeners.add(onChange);
    // Static hosting has no change feed; poll the manifest while the tab is
    // visible so edits under public/ show up during development.
    let last = '';
    let stopped = false;
    const tick = async () => {
      if (stopped || document.visibilityState !== 'visible') return;
      try {
        const resp = await fetch(`${this.base}manifest.json`, { cache: 'no-store' });
        const text = resp.ok ? await resp.text() : '';
        if (last && text && text !== last) onChange(null);
        if (text) last = text;
      } catch {
        /* offline — try again next tick */
      }
    };
    void tick();
    const timer = window.setInterval(tick, 2500);
    return () => {
      stopped = true;
      this.listeners.delete(onChange);
      window.clearInterval(timer);
    };
  }
}
